382		if _, err := l.RequestUse("NOPE"); !errors.Is(err, ErrNotFound) {
383			t.Fatalf("未知编号应报 ErrNotFound，得到 %v", err)
384		}
385		if len(l.UsageRecords()) != before {
386			t.Fatal("未知编号的使用申请不应留痕")
387		}
